23:
24:#[async_trait]
25:impl Tool for BlobCatalogTool {
26:    fn name(&self) -> &str {
27:        "blob_catalog"
28:    }
29:
30:    fn description(&self) -> &str {
31:        "Return every active plugin's sealed schema (from the SHM blob catalog) in one \
32:         payload, keyed by plugin id. Unlike per-plugin schema lookups, this gives a model \
33:         the full catalog at once so it can reason about connections across plugins.\n\
34:         Use mode='list' to get plugin IDs only (~2KB), then pass specific IDs to \
35:         mode='full' for complete schemas of just those plugins (prevents truncation)."
36:    }
