fn hex_hash(data: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(data);
    hex::encode(h.finalize())
}

fn stable_uuid(hash: &str) -> String {
    // Use first 32 hex chars of hash to form a UUID-like stable ID
    if hash.len() >= 32 {
        format!(
            "{}-{}-{}-{}-{}",
            &hash[0..8],
            &hash[8..12],
            &hash[12..16],
            &hash[16..20],
            &hash[20..32]
        )
    } else {
        uuid::Uuid::new_v4().to_string()
    }
}

